'use client';

import React from 'react';

/** Props for the {@link Dialog} component. */
export interface DialogProps extends React.DialogHTMLAttributes<HTMLDialogElement> {
  /** Whether the dialog is open. Controls the native `<dialog>` element. */
  open?: boolean;
  /** Called when the dialog requests to close (backdrop click or Escape). */
  onClose?: () => void;
  /** Additional CSS class names. */
  className?: string;
  children?: React.ReactNode;
}

/**
 * Modal overlay with dither backdrop.
 * Wraps the native `<dialog>` element and manages `showModal()`/`close()` via `useEffect`.
 */
export const Dialog = React.forwardRef<HTMLDialogElement, DialogProps>(
  ({ open, onClose, className, children, ...rest }, ref) => {
    const innerRef = React.useRef<HTMLDialogElement>(null);
    const dialogRef = (ref as React.RefObject<HTMLDialogElement>) ?? innerRef;

    React.useEffect(() => {
      const el = typeof dialogRef === 'object' && dialogRef !== null ? dialogRef.current : null;
      if (!el) return;
      if (open && !el.open) {
        el.showModal();
      } else if (!open && el.open) {
        el.close();
      }
    }, [open, dialogRef]);

    React.useEffect(() => {
      const el = typeof dialogRef === 'object' && dialogRef !== null ? dialogRef.current : null;
      if (!el || !onClose) return;
      const handler = () => onClose();
      el.addEventListener('close', handler);
      return () => el.removeEventListener('close', handler);
    }, [onClose, dialogRef]);

    // Close on backdrop click
    const handleClick = React.useCallback(
      (e: React.MouseEvent<HTMLDialogElement>) => {
        const el = typeof dialogRef === 'object' && dialogRef !== null ? dialogRef.current : null;
        if (e.target === el && onClose) onClose();
      },
      [onClose, dialogRef],
    );

    return (
      <dialog
        ref={dialogRef}
        className={`sk-dialog${className ? ` ${className}` : ''}`}
        onClick={handleClick}
        {...rest}
      >
        {children}
      </dialog>
    );
  },
);

Dialog.displayName = 'Dialog';

/** Props for the {@link DialogContent} sub-component. */
export interface DialogContentProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Content wrapper inside Dialog providing the dither border. */
export const DialogContent = React.forwardRef<HTMLDivElement, DialogContentProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-dialog__content${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

DialogContent.displayName = 'DialogContent';

/** Props for the {@link DialogHeader} sub-component. */
export interface DialogHeaderProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Dialog title text. */
  title?: string;
  /** Called when the close button is clicked. */
  onClose?: () => void;
  children?: React.ReactNode;
  className?: string;
}

/** Header section of a Dialog with title and close button. */
export const DialogHeader = React.forwardRef<HTMLDivElement, DialogHeaderProps>(
  ({ title, onClose, className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-dialog__header${className ? ` ${className}` : ''}`} {...rest}>
      {title && <h2 className="sk-dialog__title">{title}</h2>}
      {children}
      {onClose && (
        <button className="sk-dialog__close" onClick={onClose} aria-label="Close dialog">
          [x]
        </button>
      )}
    </div>
  ),
);

DialogHeader.displayName = 'DialogHeader';

/** Props for the {@link DialogBody} sub-component. */
export interface DialogBodyProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Body section of a Dialog. */
export const DialogBody = React.forwardRef<HTMLDivElement, DialogBodyProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-dialog__body${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

DialogBody.displayName = 'DialogBody';

/** Props for the {@link DialogFooter} sub-component. */
export interface DialogFooterProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Footer section of a Dialog, typically containing action buttons. */
export const DialogFooter = React.forwardRef<HTMLDivElement, DialogFooterProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-dialog__footer${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

DialogFooter.displayName = 'DialogFooter';

/**
 * skeehn — Dialog Component
 *
 * @component sk-dialog (uses <dialog> element)
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    [open] | [data-loading] | [data-skeleton]
 * @slots     __content | __header | __title | __close | __body | __footer
 * @a11y      Native dialog focus trapping, Escape to close, backdrop click
 * @print     Content visible, backdrop and animations hidden
 */

.sk-dialog { padding: 0; border: none; border-radius: var(--sk-radius); background: transparent; max-width: 28rem; width: 90vw; font-family: var(--sk-font-mono); }
.sk-dialog::backdrop { background: hsl(var(--sk-foreground) / 0.6); backdrop-filter: blur(2px); }
.sk-dialog__content { position: relative; background: hsl(var(--sk-background)); border: 2px solid hsl(var(--sk-foreground)); border-radius: var(--sk-radius); overflow: hidden; }
.sk-dialog__content::before { content: ""; position: absolute; inset: 0; background-image: var(--sk-dither-pattern); background-repeat: repeat; opacity: calc(var(--sk-dither-opacity, 0.15) * 0.3); pointer-events: none; }
.sk-dialog__header { display: flex; justify-content: space-between; align-items: center; padding: var(--sk-space-3) var(--sk-space-4); border-bottom: var(--sk-border); position: relative; z-index: 1; }
.sk-dialog__title { margin: 0; font-family: var(--sk-font-mono); font-size: var(--sk-font-size-sm); font-weight: 600; letter-spacing: 0.02em; text-transform: uppercase; }
.sk-dialog__close { background: none; border: var(--sk-border); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); cursor: pointer; padding: var(--sk-space-1) var(--sk-space-2); color: hsl(var(--sk-muted-foreground)); transition: all var(--sk-transition-fast); }
.sk-dialog__close:hover { color: hsl(var(--sk-foreground)); background: hsl(var(--sk-accent)); }
.sk-dialog__body { padding: var(--sk-space-4); position: relative; z-index: 1; }
.sk-dialog__body p { margin: 0; color: hsl(var(--sk-muted-foreground)); font-size: var(--sk-font-size-sm); line-height: var(--sk-line-height); }
.sk-dialog__footer { display: flex; justify-content: flex-end; gap: var(--sk-space-2); padding: var(--sk-space-3) var(--sk-space-4); border-top: var(--sk-border); position: relative; z-index: 1; }

/* Micro-interactions */
.sk-dialog[open] { animation: sk-scale-up var(--sk-anim-normal, 300ms) var(--sk-ease-pixel, cubic-bezier(0.25, 0.46, 0.45, 0.94)) both; }
@keyframes sk-scale-up { from { transform: scale(0.95); opacity: 0; } to { transform: scale(1); opacity: 1; } }

.sk-dialog__close:focus-visible { outline: 2px solid hsl(var(--sk-ring)); outline-offset: 2px; }

/* Pixel variant */
.sk-dialog[data-variant="pixel"] .sk-dialog__content {
  border: 3px solid hsl(var(--sk-foreground));
  box-shadow: 6px 6px 0 hsl(var(--sk-foreground));
}

/* Retro variant */
.sk-dialog[data-variant="retro"] .sk-dialog__content {
  border: 2px solid hsl(var(--sk-foreground));
  box-shadow: 0 0 20px hsl(var(--sk-foreground) / 0.1);
}
.sk-dialog[data-variant="retro"] .sk-dialog__content::before {
  background-image: var(--sk-dither-scanlines);
  background-size: 100% 4px;
  opacity: 0.03;
}

/* ASCII variant */
.sk-dialog[data-variant="ascii"] .sk-dialog__content { border: none; background: hsl(var(--sk-background)); }
.sk-dialog[data-variant="ascii"] .sk-dialog__header { border-bottom: 1px dashed hsl(var(--sk-border-color)); }
.sk-dialog[data-variant="ascii"] .sk-dialog__footer { border-top: 1px dashed hsl(var(--sk-border-color)); }

/* Loading */
.sk-dialog[data-loading] .sk-dialog__body { position: relative; opacity: 0.6; pointer-events: none; }
.sk-dialog[data-loading] .sk-dialog__body::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--sk-dither-pattern);
  background-repeat: repeat;
  opacity: 0.06;
  animation: sk-pulse-dither 2s ease-in-out infinite;
  pointer-events: none;
}

/* Skeleton */
.sk-dialog[data-skeleton] .sk-dialog__title,
.sk-dialog[data-skeleton] .sk-dialog__body p {
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-radius: var(--sk-radius);
}

@media print {
  .sk-dialog { position: static; max-width: 100%; width: 100%; }
  .sk-dialog::backdrop { display: none; }
  .sk-dialog__content { box-shadow: none; border: 1px solid hsl(var(--sk-foreground)); }
  .sk-dialog[data-skeleton] { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-dialog[open] { animation: none; }
  .sk-dialog__close { transition: none; }
  .sk-dialog[data-skeleton] .sk-dialog__title,
  .sk-dialog[data-skeleton] .sk-dialog__body p { animation: none; background: hsl(var(--sk-muted)); }
}
